const cvContent = $("Create Tailored CV Content").item.json;

const cvPdf = $("Upload CV PDF to Baserow").first().json;
const cvTex = $("Upload CV TEX to Baserow").first().json;
const coverPdf = $("Upload Cover Letter PDF to Baserow").first().json;
const coverTex = $("Upload Cover Letter TEX to Baserow").first().json;

const requiredUpload = (upload, label) => {
  if (!upload || typeof upload.name !== "string" || !upload.name.trim()) {
    throw new Error(`${label} did not return a valid Baserow user-file name.`);
  }
  return upload;
};

requiredUpload(cvPdf, "CV PDF upload");
requiredUpload(cvTex, "CV TEX upload");
requiredUpload(coverPdf, "Cover letter PDF upload");
requiredUpload(coverTex, "Cover letter TEX upload");

const rowId = Number($("Prepare CV Content Input").item.json.baserow_row_id);
if (!Number.isInteger(rowId) || rowId <= 0) {
  throw new Error("The job context does not contain a valid Baserow row ID.");
}

const applicationId = String(cvContent.application_id ?? "application");

return [{
  json: {
    rowId,
    "Cover Letter": [
      {
        "name": coverPdf.name,
        "visible_name": `cover-letter_${applicationId}.pdf`
      },
      {
        "name": coverTex.name,
        "visible_name": `cover-letter_${applicationId}.tex`
      }
    ],
    "CV": [
      {
        "name": cvPdf.name,
        "visible_name": `cv_${applicationId}.pdf`
      },
      {
        "name": cvTex.name,
        "visible_name": `cv_${applicationId}.tex`
      }
    ]
  }
}];

const submission = $input.first().json ?? {};
const questions = submission.questions ?? {};

const FIELD_IDS = {
  entryType: "entryType",
  linkedinJobId: "6Ze685Zcm27s3sV6xAdg6w",
  companyName: "tccyk1pB8iRUf1NGCDbcP5",
  jobTitle: "mV2wYQbu1b1Jhf1gTDAbK8",
  jobDescription: "98TcaL2qnS8Y31TQxgZaZD",
  jobUrl: "1gZ3kT2Db3G3y2QhYfjT8X",
  location: "oc63gzWN4vxEJwx8nzZrAK",
  contractType: "g2VK5MiabTgDTUXGYhnV4q",
  publishedAt: "sYghUzUtSwi8T4yaReYefR",
  jobId: "2XDTXJHaY2BJEndo3EgEAV",
  pageContent: "uAXUdaYv4cjhWqtZiFYWc7",
};

const normalizeValue = (value) => {
  if (value === undefined || value === null) return "";

  if (Array.isArray(value)) {
    return value.map(normalizeValue).filter((item) => item !== "").join(", ");
  }

  if (typeof value === "object") {
    for (const key of ["value", "label", "name", "url", "text", "optionId", "id"]) {
      if (value[key] !== undefined && value[key] !== null) {
        return normalizeValue(value[key]);
      }
    }
    return JSON.stringify(value);
  }

  return String(value).trim();
};

const questionValue = (fieldId, expectedName) => {
  const direct = questions[fieldId];

  if (direct !== undefined) {
    if (direct && typeof direct === "object" && "value" in direct) {
      return normalizeValue(direct.value);
    }
    return normalizeValue(direct);
  }

  const match = Object.values(questions).find((question) => {
    if (!question || typeof question !== "object") return false;
    const name = normalizeValue(question.name ?? question.label);
    return name.toLowerCase() === expectedName.toLowerCase();
  });

  return match && typeof match === "object" && "value" in match
    ? normalizeValue(match.value)
    : normalizeValue(match);
};

const entryTypeRaw = questionValue(FIELD_IDS.entryType, "Entry Type");
const entryType =
  entryTypeRaw.toLowerCase() === "linkedin"
    ? "LinkedIn"
    : entryTypeRaw.toLowerCase() === "external"
      ? "External"
      : entryTypeRaw.toLowerCase() === "ai"
        ? "AI"
        : entryTypeRaw;

if (!["LinkedIn", "External", "AI"].includes(entryType)) {
  throw new Error(`Fillout submission has an invalid Entry Type: "${entryTypeRaw}".`);
}

const linkedinJobId = questionValue(FIELD_IDS.linkedinJobId, "LinkedIn Job ID")
  .replace(/\s+/g, "");

if (entryType === "LinkedIn" && !/^\d+$/.test(linkedinJobId)) {
  throw new Error("LinkedIn Job ID is required and must contain only digits.");
}

const linkedinJobUrl = linkedinJobId
  ? `https://www.linkedin.com/jobs/view/${linkedinJobId}`
  : "";

const parsed = {
  entryType,
  linkedinJobId,
  linkedinJobUrl,
  companyName: questionValue(FIELD_IDS.companyName, "Company Name"),
  jobTitle: questionValue(FIELD_IDS.jobTitle, "Job Title"),
  jobDescription: questionValue(FIELD_IDS.jobDescription, "Job Description"),
  jobUrl: questionValue(FIELD_IDS.jobUrl, "Job URL"),
  location: questionValue(FIELD_IDS.location, "Location"),
  contractType: questionValue(FIELD_IDS.contractType, "Contract Type"),
  publishedAt: questionValue(FIELD_IDS.publishedAt, "Published Date"),
  jobId: entryType === "LinkedIn"
    ? linkedinJobId
    : questionValue(FIELD_IDS.jobId, "External Job ID"),
  pageContent: questionValue(FIELD_IDS.pageContent, "Page Content"),
};

if (entryType === "External") {
  for (const [field, label] of [
    ["companyName", "Company Name"],
    ["jobTitle", "Job Title"],
    ["jobDescription", "Job Description"],
    ["jobUrl", "Job URL"],
  ]) {
    if (!parsed[field]) {
      throw new Error(`${label} is required for External entries.`);
    }
  }
}

if (entryType === "AI" && !parsed.pageContent) {
  throw new Error("Page Content is required for AI entries.");
}

return [{
  json: {
    ...parsed,
    filloutSubmissionId: submission.submissionId ?? submission.id ?? "",
    filloutFormId: submission.formId ?? "",
    filloutSubmittedAt: submission.submissionTime ?? submission.createdAt ?? "",
  },
  pairedItem: { item: 0 },
}];

const resolved = $json;
const job = resolved.source_job ?? resolved;

const singleLine = (value) => String(value ?? "")
  .replace(/[\r\n\t]+/g, " ")
  .replace(/\s{2,}/g, " ")
  .trim();

const multiLine = (value) => String(value ?? "")
  .replace(/\r\n?/g, "\n")
  .trim();

const positiveInteger = (value, label) => {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number <= 0) {
    throw new Error(`${label} must be a safe positive integer.`);
  }
  return number;
};

const normalizeDate = (value) => {
  const raw = String(value ?? "").trim();

  if (!raw) {
    return new Date().toISOString().slice(0, 10);
  }

  const exactDate = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (exactDate) {
    const parsedExact = new Date(`${raw}T00:00:00Z`);
    if (
      !Number.isNaN(parsedExact.getTime()) &&
      parsedExact.toISOString().slice(0, 10) === raw
    ) {
      return raw;
    }
  }

  const parsed = new Date(raw);
  if (Number.isNaN(parsed.getTime())) {
    throw new Error(
      `Date "${raw}" could not be converted to the required YYYY-MM-DD format.`
    );
  }

  return parsed.toISOString().slice(0, 10);
};

const normalizeUrl = (value) => {
  const raw = String(value ?? "").trim();
  if (!raw) return null;

  const normalized = raw.startsWith("//") ? "https:" + raw : raw;
  if (!/^https?:\/\/[^\s]+$/i.test(normalized)) {
    throw new Error("Link \"" + raw + "\" is not a valid HTTP(S) URL.");
  }

  return normalized;
};

const CONTRACT_TYPE_IDS = {
  "full-time": 6954765,
  "full time": 6954765,
  "fulltime": 6954765,
  "permanent": 6954765,
  "regular": 6954765,
  "regular full-time": 6954765,
  "regular full time": 6954765,
  "contract": 6954766,
  "contractor": 6954766,
  "freelance": 6954766,
  "fixed term": 6954766,
  "fixed-term": 6954766,
  "independent contractor": 6954766,
  "part-time": 6954767,
  "part time": 6954767,
  "parttime": 6954767,
  "temporary": 6954768,
  "temp": 6954768,
  "seasonal": 6954768,
  "casual": 6954768,
  "term": 6954768,
  "term position": 6954768,
  "internship": 6954769,
  "intern": 6954769,
  "co-op": 6954769,
  "co op": 6954769,
  "student placement": 6954769,
  "volunteer": 6954770,
  "unpaid volunteer": 6954770,
};
const VALID_CONTRACT_IDS = new Set(Object.values(CONTRACT_TYPE_IDS));

const normalizeContractType = (value) => {
  if (value === undefined || value === null || String(value).trim() === "") {
    return null;
  }

  const numeric = Number(value);
  if (Number.isInteger(numeric) && VALID_CONTRACT_IDS.has(numeric)) {
    return numeric;
  }

  const key = singleLine(value).toLowerCase();
  return CONTRACT_TYPE_IDS[key] ?? null;
};

const STATUS_IDS = {
  "new": 6955262,
  "dropped": 6978563,
  "to apply": 6983774,
  "applied": 6955263,
  "rejected": 6955264,
  "interview": 6955265,
  "offered": 6955266,
};
const VALID_STATUS_IDS = new Set(Object.values(STATUS_IDS));

const normalizeStatus = (value) => {
  if (value !== undefined && value !== null && String(value).trim() !== "") {
    const numeric = Number(value);
    if (Number.isInteger(numeric) && VALID_STATUS_IDS.has(numeric)) {
      return numeric;
    }
    const key = singleLine(value).toLowerCase();
    if (STATUS_IDS[key]) return STATUS_IDS[key];
  }
  return STATUS_IDS.new;
};

const companyName = singleLine(job.companyName);
const jobTitle = singleLine(job.jobTitle);
const jobDescription = multiLine(job.jobDescription);

if (!companyName) throw new Error("Company Name is required.");
if (!jobTitle) throw new Error("Title is required.");
if (!jobDescription) throw new Error("Job Description is required.");

return [{
  json: {
    rowId: resolved.baserow_row_id ?? null,
    record_exists: Boolean(resolved.record_exists),
    source_job: job,
    "Job ID": positiveInteger(job.jobId, "Job ID"),
    "Date": normalizeDate(job.publishedAt),
    "Company Name": companyName,
    "Title": jobTitle,
    "Location": singleLine(job.location),
    "Job Description": jobDescription,
    "Contract Type": normalizeContractType(job.contractType),
    "Link": normalizeUrl(job.jobUrl),
    "Status": normalizeStatus(job.status ?? "New")
  }
}];

const rowResult = $input.first().json;
const metadata = $("Build Initial Job Row").item.json;
const job = metadata.source_job;
const rowId = Number(rowResult?.id ?? metadata.rowId);

if (!Number.isInteger(rowId) || rowId <= 0) {
  throw new Error("The Baserow metadata upsert did not return a valid row ID.");
}

return [{
  json: {
    ...job,
    baserow_row_id: rowId
  }
}];

const job = { ...$("Use Single Job Input").item.json };

const rows = $input.all().map((item) => {
  const source = item.json?.fields && typeof item.json.fields === "object"
    ? { ...item.json.fields, id: item.json.id }
    : item.json;
  return source && typeof source === "object" ? source : {};
});

const parsePositiveInteger = (value) => {
  if (value === undefined || value === null || String(value).trim() === "") {
    return null;
  }

  const number = Number(String(value).trim());
  if (!Number.isSafeInteger(number) || number <= 0) {
    throw new Error(`Job ID "${value}" must be a safe positive integer.`);
  }
  return number;
};

const existingIds = new Set();
for (const row of rows) {
  const value = parsePositiveInteger(row?.["Job ID"]);
  if (value !== null) existingIds.add(value);
}

const preferredJobId = parsePositiveInteger(
  job.externalJobId ?? job.external_job_id ?? job.jobId
);

let targetJobId = preferredJobId;
if (targetJobId === null) {
  let candidate = existingIds.size > 0
    ? Math.max(...existingIds) + 1
    : 1;

  while (existingIds.has(candidate)) candidate += 1;

  if (!Number.isSafeInteger(candidate) || candidate <= 0) {
    throw new Error("Could not generate a safe unique Job ID.");
  }
  targetJobId = candidate;
}

const matchingRows = rows.filter((row) => {
  const rowJobId = parsePositiveInteger(row?.["Job ID"]);
  return rowJobId === targetJobId;
});

if (matchingRows.length > 1) {
  throw new Error(`Multiple Baserow rows use Job ID ${targetJobId}.`);
}

const existing = matchingRows[0];
job.jobId = targetJobId;
job.externalJobId = preferredJobId;

return [{
  json: {
    source_job: job,
    record_exists: Boolean(existing?.id),
    baserow_row_id: existing?.id ?? null,
    generated_job_id: preferredJobId === null,
  },
}];

